WITH metrics AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY device ORDER BY started_at, id) AS seq_no, LAST_VALUE(browser, TRUE) OVER (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser, ROW_NUMBER() OVER (ORDER BY started_at DESC, id) AS event_seq, FIRST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_browser, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at DESC, id) AS row_seq FROM sessions), not_flagged AS (SELECT s.* FROM metrics s WHERE NOT EXISTS (SELECT 1 FROM web_events x WHERE x.session_id = s.id AND x.event_time <= s.started_at)), with_latest AS (SELECT s.*, top1.web_event_duration_sec, top1.web_event_page FROM not_flagged s JOIN LATERAL (SELECT c.duration_sec AS web_event_duration_sec, c.page AS web_event_page FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) top1 ON TRUE), scored AS (SELECT *, FIRST_VALUE(seq_no) IGNORE NULLS OVER (ORDER BY row_seq, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_seq_no, NTILE(3) OVER (ORDER BY row_seq DESC, id) AS row_seq_bucket, ROUND(seq_no / SUM(seq_no) OVER (PARTITION BY browser), 4) AS seq_no_share, LEAD(seq_no, 1) OVER (PARTITION BY browser ORDER BY seq_no, id) AS next_seq_no FROM with_latest WHERE web_event_duration_sec <> 444), with_windows AS (SELECT id, browser, country, first_known_browser, row_seq, web_event_page, first_known_seq_no, seq_no_share, COUNT(next_seq_no) OVER (ORDER BY CAST(started_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS next_seq_no_count_30d, SUM(event_seq) OVER w_recent AS running_event_seq, LAST_VALUE(web_event_duration_sec, TRUE) OVER (PARTITION BY web_event_page ORDER BY first_known_seq_no, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_web_event_duration_sec, NTILE(5) OVER w_grp AS web_event_duration_sec_bucket, FIRST_VALUE(web_event_duration_sec, TRUE) OVER (PARTITION BY customer_id, browser ORDER BY seq_no_share, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_web_event_duration_sec FROM scored WINDOW w_recent AS (PARTITION BY country ORDER BY next_seq_no, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_grp AS (PARTITION BY customer_id ORDER BY web_event_duration_sec DESC, id)), scored_sessions AS (SELECT *, AVG(first_known_seq_no) OVER (PARTITION BY browser, country ORDER BY first_known_web_event_duration_sec, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS first_known_seq_no_avg_6, SUM(first_known_seq_no) OVER (PARTITION BY browser ORDER BY web_event_duration_sec_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_first_known_seq_no FROM with_windows) SELECT id, browser, country, first_known_browser, web_event_page, first_known_seq_no, seq_no_share, next_seq_no_count_30d, last_known_web_event_duration_sec FROM scored_sessions ORDER BY next_seq_no_count_30d DESC, country
